import{_ as t,a,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Returns (RMA)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/returns/index.md","filePath":"api/graphql-api/admin/sales/returns/index.md","lastUpdated":1787290888000}'),n={name:"api/graphql-api/admin/sales/returns/index.md"};function o(d,e,i,u,c,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="returns-rma" tabindex="-1">Returns (RMA) <a class="header-anchor" href="#returns-rma" aria-label="Permalink to &quot;Returns (RMA)&quot;">​</a></h1><p>The Returns menu is the admin queue for <strong>RMA (Return Merchandise Authorization) requests</strong> — the returns and item-cancellations customers raise against their orders. It mirrors the admin <strong>Sales → Returns</strong> screen: browse the queue, open a request for detail, create a return for any order, move a request through its status workflow, reopen a closed one, and exchange messages with the customer.</p><h2 id="what-a-return-holds" tabindex="-1">What a return holds <a class="header-anchor" href="#what-a-return-holds" aria-label="Permalink to &quot;What a return holds&quot;">​</a></h2><p>Each RMA request records the order it belongs to (<code>orderId</code> / <code>orderIncrementId</code> / <code>orderStatus</code>), the customer context (<code>customerName</code> / <code>customerEmail</code> / <code>isGuest</code>), the current status (<code>statusId</code> / <code>statusTitle</code> / <code>statusColor</code>), the package condition, an optional <code>information</code> note, and the single returned item (<code>item</code>) with its resolution (<code>return</code> or a <code>cancel_items</code> cancellation) and reason. Attached proof images are listed in <code>images</code>.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A request moves through a set of statuses (Pending, Accept, Declined, Dispatched package, Received package, Item canceled, …). Each request&#39;s <code>availableStatuses</code> field lists the exact status transitions the admin may set next — use those ids when calling <strong>Update Status</strong>.</p><h2 id="update-status-—-the-action-semantics" tabindex="-1">Update Status — the action semantics <a class="header-anchor" href="#update-status-—-the-action-semantics" aria-label="Permalink to &quot;Update Status — the action semantics&quot;">​</a></h2><p>Setting a status is more than a label change for two special statuses:</p><ul><li><strong>Received package</strong> — creates a <strong>refund</strong> for the returned item. Send a <code>shipping</code> amount to include shipping in the refund; omit or send <code>0</code> to refund the item only.</li><li><strong>Item canceled</strong> — <strong>cancels the order item</strong> and restores its inventory.</li></ul><p>Any other status just updates the status. Every status change adds a note to the conversation and notifies the customer.</p><h2 id="reopen" tabindex="-1">Reopen <a class="header-anchor" href="#reopen" aria-label="Permalink to &quot;Reopen&quot;">​</a></h2><p>A declined or canceled request can be <strong>reopened</strong> back to Pending when store settings allow it (otherwise the mutation returns an error). The <code>canReopen</code> flag on the detail tells you whether reopening is currently possible.</p><h2 id="creating-a-return" tabindex="-1">Creating a return <a class="header-anchor" href="#creating-a-return" aria-label="Permalink to &quot;Creating a return&quot;">​</a></h2><p>To open a return for an order, first list the order&#39;s <strong>returnable items</strong> (<code>adminReturnableItems</code>) to get the trusted quantity caps, and the active <strong>return reasons</strong> (<code>adminReturnReasons</code>) for the chosen resolution type, then call <strong>Create Return</strong>. <code>rmaQty</code> is capped server-side by the item&#39;s returnable/cancelable quantity.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><p>Each request has a conversation thread. <strong>List Messages</strong> returns the thread newest-first; <strong>Send Message</strong> posts an admin reply and notifies the customer.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./queries/list-returns.html">List Returns</a></td><td><code>adminReturns</code> query</td></tr><tr><td><a href="./queries/view-return.html">View Return</a></td><td><code>adminReturn(id:)</code> query</td></tr><tr><td><a href="./queries/list-returnable-items.html">List Returnable Items</a></td><td><code>adminReturnableItems(orderId:)</code> query</td></tr><tr><td><a href="./queries/list-return-reasons.html">List Return Reasons</a></td><td><code>adminReturnReasons(resolutionType:)</code> query</td></tr><tr><td><a href="./queries/list-return-messages.html">List Return Messages</a></td><td><code>adminReturnMessages(returnId:)</code> query</td></tr><tr><td><a href="./mutations/create-return.html">Create Return</a></td><td><code>createAdminReturn</code> mutation</td></tr><tr><td><a href="./mutations/update-status.html">Update Status</a></td><td><code>updateStatusAdminReturn</code> mutation</td></tr><tr><td><a href="./mutations/reopen-return.html">Reopen Return</a></td><td><code>reopenAdminReturn</code> mutation</td></tr><tr><td><a href="./mutations/send-return-message.html">Send Message</a></td><td><code>createAdminReturnMessage</code> mutation</td></tr></tbody></table><p>Permissions: <code>sales.rma.requests</code> for reads / status changes / reopen / messages, and <code>sales.rma.requests.create</code> to create a return.</p>',19)]))}const p=t(n,[["render",o]]);export{m as __pageData,p as default};
